\title{The Gaussian Integer Parametrization of Pythagorean Triples}
\author{Aristotle}
\date{2026-06-30}

\begin{document}

\begin{abstract}
We give a complete, self-contained development of the classical correspondence
between Pythagorean triples and the Gaussian integers $\Zi$. The norm map
$N(a + b\,i) = a^2 + b^2$ encodes sums of two squares, which makes $\Zi$ the
natural algebraic home for the equation $x^2 + y^2 = c^2$. We define the
parametrization $P$ that sends $z = a + b\,i$ to the triple
$(|a^2 - b^2|,\ 2|ab|,\ a^2 + b^2)$ and prove four results: (1) every output is
a Pythagorean triple, via the multiplicativity of the norm; (2) the
parametrization is injective up to the eight-element symmetry group generated by
the four units of $\Zi$ together with complex conjugation; (3) it is surjective
onto the primitive Pythagorean triples with odd first leg; and (4) the legs of
$P(z)$ are coprime if and only if $\Re z$ and $\Im z$ are coprime and of opposite
parity. We correct two folklore statements: the injectivity statement requires
conjugation in addition to unit multiplication, and the primitivity criterion
requires an opposite-parity hypothesis beyond mere coprimality of the parts.
\end{abstract}

\maketitle

\section{Introduction}

A \emph{Pythagorean triple} is a triple of integers $(a, b, c)$ satisfying
$a^2 + b^2 = c^2$. The classification of such triples is among the oldest
problems in number theory. The classical parametrization $a = m^2 - n^2$,
$b = 2mn$, $c = m^2 + n^2$ generates them, but the reason it works---and the
precise sense in which it is exhaustive and non-redundant---is illuminated by
passing to the \emph{Gaussian integers}
\[
  \Zi = \{a + b\,i : a, b \in \Z\}, \qquad i^2 = -1.
\]
The ring $\Zi$ carries the \emph{norm}
\[
  N(a + b\,i) = (a + b\,i)(a - b\,i) = a^2 + b^2,
\]
a multiplicative map $N : \Zi \to \Z_{\ge 0}$. Because the norm \emph{is} a sum
of two squares and is multiplicative, squaring a Gaussian integer produces a
Pythagorean triple. We make that observation precise and push it to a complete
classification.

\section{Definitions}

Throughout, $a = \Re z$ and $b = \Im z$ denote the real and imaginary parts of
$z = a + b\,i$.

\begin{definition}[Pythagorean triple]
$\mathcal{P} = \{(x, y, c) \in \Z^3 : x^2 + y^2 = c^2\}$.
\end{definition}

\begin{definition}[Primitive triple]
A triple $(x, y, c) \in \mathcal{P}$ is \emph{primitive} if $\gcdop(x, y) = 1$.
\end{definition}

\begin{definition}[Norm]
$N(a + b\,i) = a^2 + b^2$, and $N(zw) = N(z)\,N(w)$ for all $z, w \in \Zi$.
\end{definition}

\begin{definition}[Units]
The units of $\Zi$ are exactly the elements of norm $1$:
$\Zi^\times = \{1, -1, i, -i\}$.
\end{definition}

\begin{definition}[Conjugation]
$\overline{a + b\,i} = a - b\,i$; conjugation is a norm-preserving ring
automorphism of $\Zi$.
\end{definition}

\begin{definition}[The Gaussian parametrization]
$P : \Zi \to \mathcal{P}$ is defined by
\[
  P(z) = \bigl(\,|a^2 - b^2|,\ 2|ab|,\ a^2 + b^2\,\bigr), \qquad z = a + b\,i.
\]
\end{definition}

\section{Validity}

\begin{theorem}[Validity]
For every $z = a + b\,i \in \Zi$,
\[
  |a^2 - b^2|^2 + (2|ab|)^2 = (a^2 + b^2)^2.
\]
\end{theorem}

\begin{proof}
Squaring removes the absolute values, so the left side equals
$(a^2 - b^2)^2 + 4a^2 b^2 = a^4 - 2a^2 b^2 + b^4 + 4a^2 b^2
= a^4 + 2a^2 b^2 + b^4 = (a^2 + b^2)^2$. Conceptually, the identity is the
statement $N(z^2) = N(z)^2$: since $z^2 = (a^2 - b^2) + (2ab)i$ we have
$N(z^2) = (a^2 - b^2)^2 + (2ab)^2$, while multiplicativity gives
$N(z^2) = (a^2 + b^2)^2$.
\end{proof}

\section{Rigidity (injectivity up to symmetry)}

\begin{theorem}[Rigidity]
Suppose $P(z) = P(w)$. Then there is a unit $u \in \{1, -1, i, -i\}$ with
$z = u\,w$ or $z = u\,\overline{w}$.
\end{theorem}

\begin{proof}[Proof sketch]
Write $a = \Re z$, $b = \Im z$, $a' = \Re w$, $b' = \Im w$. Equality
$P(z) = P(w)$ gives $a^2 + b^2 = a'^2 + b'^2$ and $(ab)^2 = (a'b')^2$. From these
symmetric constraints one verifies $(a^2 - a'^2)(a^2 - b'^2) = 0$, so either
$a^2 = a'^2,\ b^2 = b'^2$, or $a^2 = b'^2,\ b^2 = a'^2$. Hence
$\{|a|, |b|\} = \{|a'|, |b'|\}$. In the first case the independent sign choices in
$(a, b) = (\pm a', \pm b')$ are realized by a unit times $w$ or its conjugate; in
the second case the parts are swapped, which is conjugation composed with a unit.
Either way $z = uw$ or $z = u\overline{w}$.
\end{proof}

\begin{remark}
It is sometimes claimed that $P(z) = P(w)$ forces $z, w$ to differ by a unit
alone. This is false: $P$ records the legs as an unordered pair and cannot
distinguish $z$ from $\overline{z}$, and conjugation is not multiplication by a
unit (e.g.\ $\overline{1 + 2i} = 1 - 2i$ is no unit multiple of $1 + 2i$). The
correct fiber description must include conjugation.
\end{remark}

\section{Completeness (surjectivity)}

\begin{theorem}[Completeness]
Let $(x, y, c)$ be a primitive Pythagorean triple with $x$ odd, $y$ even, and
$x, y, c > 0$. Then there exist coprime integers $m > n > 0$ of opposite parity
with $(x, y, c) = (m^2 - n^2,\ 2mn,\ m^2 + n^2) = P(m + n\,i)$.
\end{theorem}

\begin{proof}[Proof sketch]
From $x^2 = (c - y)(c + y)$ and primitivity, $c - y$ and $c + y$ are coprime;
their product being a square forces each to be a square, $c + y = m^2$,
$c - y = n^2$. Solving gives $x = mn$, $y = (m^2 - n^2)/2$, $c = (m^2 + n^2)/2$
(matching the standard form after rescaling), with $m > n > 0$ coprime and of
opposite parity. Thus $(x, y, c) = P(m + n\,i)$.
\end{proof}

\section{The primitivity criterion}

\begin{theorem}[Primitivity criterion]
For $z = a + b\,i$, the legs of $P(z)$ satisfy
$\gcdop(|a^2 - b^2|, 2|ab|) = 1$ if and only if
$\gcdop(a, b) = 1$ and $a \not\equiv b \pmod 2$.
\end{theorem}

\begin{proof}[Proof sketch]
($\Rightarrow$) If a prime $p \mid a$ and $p \mid b$, then $p$ divides both legs.
If $a \equiv b \pmod 2$, then both $a^2 - b^2$ and $2ab$ are even. Either way the
legs are not coprime.

($\Leftarrow$) If $\gcdop(a, b) = 1$ and $a, b$ have opposite parity, then
$a^2 - b^2$ is odd, ruling out a shared factor $2$. If an odd prime $p$ divides
both legs, then $p \mid ab$, so $p \mid a$ or $p \mid b$; combined with
$p \mid a^2 - b^2$ this forces $p$ to divide both $a$ and $b$, contradicting
coprimality. Hence the legs are coprime.
\end{proof}

\begin{remark}
The naive criterion ``legs coprime iff $\gcdop(a, b) = 1$'' is false:
$z = 3 + i$ has coprime parts but $P(z) = (8, 6, 10)$ with $\gcdop(8,6) = 2$. The
opposite-parity clause is indispensable.
\end{remark}

\section{Algorithms}

\textbf{Generate.} Given $(a, b)$, output $(|a^2 - b^2|, 2|ab|, a^2 + b^2)$;
correctness is the Validity theorem.

\textbf{Enumerate.} Iterate over $m > n > 0$ with $\gcdop(m, n) = 1$ and
$m \not\equiv n \pmod 2$, emitting $P(m + n\,i)$ while $m^2 + n^2 \le C$; by the
Completeness and Primitivity theorems this lists each positive primitive triple
with odd first leg exactly once.

\textbf{Invert.} Given a primitive triple with odd first leg, recover $(m, n)$
from the square factorization $c + y = m^2$, $c - y = n^2$ (up to the symmetry
group of the Rigidity theorem).

\section{Discussion and future work}

The fibers of $P$ are orbits of an eight-element group: four units (lattice
symmetry) and conjugation (the invisible leg-swap). Both folklore corrections are
the unique fixes that make near-true statements exactly true. Future directions
include parametrization by higher powers $z^k$, the Eisenstein analogue for
$a^2 + ab + b^2 = c^2$, and quantitative counting of primitive triples via the
norm form.

\end{document}

